import { ArrowRight } from "lucide-react";
import MarketGlobe from "@/components/globe/MarketGlobe";
import { ButtonLink } from "@/components/site/ButtonLink";

/** Fixed globe size on desktop; on smaller screens it shrinks to the available width. */
const GLOBE_PX = 680;

export function Hero() {
  return (
    <section aria-labelledby="hero-title" className="relative overflow-hidden">
      {/* subtle brand glow */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 -z-10 bg-[radial-gradient(60%_55%_at_75%_40%,var(--brand-soft),transparent_70%),radial-gradient(40%_40%_at_10%_0%,var(--bg-soft),transparent_70%)]"
      />
      <div className="mx-auto grid max-w-7xl items-center gap-10 px-4 pt-10 pb-16 sm:px-6 md:pt-14 lg:grid-cols-[minmax(0,1fr)_680px] lg:gap-8 lg:pb-20">
        <div className="max-w-2xl">
          <p className="inline-flex items-center gap-2 rounded-full bg-surface px-3.5 py-1.5 text-sm font-medium text-brand-deep ring-1 ring-line">
            <span className="size-2 rounded-full bg-brand" aria-hidden />
            AI for product decision making
          </p>
          <h1
            id="hero-title"
            className="mt-6 text-5xl font-semibold tracking-tight text-ink text-balance sm:text-6xl lg:text-[4.5rem] lg:leading-[1.02]"
          >
            Hear every market. <span className="text-brand">Decide with a reason.</span>
          </h1>
          <p className="mt-6 max-w-xl text-xl leading-relaxed text-ink-soft text-pretty">
            Dixi listens to customers in every market, weighs every signal and turns it into requirements for the
            next BMW. Each one traces back to its source.
          </p>
          <div className="mt-9 flex flex-wrap gap-3">
            <ButtonLink href="/dashboard">
              Open dashboard <ArrowRight className="size-4" aria-hidden />
            </ButtonLink>
            <ButtonLink href="#process" variant="secondary">
              See how it works
            </ButtonLink>
          </div>
        </div>

        <div className="relative mx-auto w-full" style={{ maxWidth: GLOBE_PX }}>
          <MarketGlobe variant="hero" />
        </div>
      </div>
    </section>
  );
}
/* Three-layer model with illustrative default weight shares per model. */

const LAYERS = [
  {
    key: "L1",
    name: "Principles",
    line: "Hard rules per market, owned by managers. Example: in Japan, the car must fit multi-storey car parks.",
    bar: "bg-l1 text-white",
    chip: "bg-l1-soft text-l1",
  },
  {
    key: "L2",
    name: "Evidence",
    line: "Customer studies, owner feedback, sales and quality reports. The main engine.",
    bar: "bg-l2 text-white",
    chip: "bg-l2-soft text-l2",
  },
  {
    key: "L3",
    name: "Signals",
    line: "Social media, search trends and concept tests. Low weight, tuned per model.",
    bar: "bg-l3 text-brand-deep",
    chip: "bg-l3-soft text-brand-deep",
  },
] as const;

const MODELS = [
  { name: "7 Series", note: "Signals barely count", weights: [55, 43, 2] },
  { name: "1 Series", note: "Younger buyers, more signal", weights: [45, 35, 20] },
];

export function LayerWeights() {
  return (
    <div className="mt-16 grid gap-10 rounded-card bg-surface p-6 shadow-card ring-1 ring-line sm:p-8 lg:grid-cols-[1fr_1.1fr] lg:gap-14">
      <div>
        <h3 className="text-xl font-semibold tracking-tight text-ink">Three layers, weighed per model</h3>
        <ul className="mt-6 space-y-5">
          {LAYERS.map((l) => (
            <li key={l.key} className="flex gap-4">
              <span className={`mt-0.5 h-6 shrink-0 rounded-md px-2 font-mono text-xs leading-6 font-semibold ${l.chip}`}>{l.key}</span>
              <div>
                <p className="font-semibold text-ink">{l.name}</p>
                <p className="mt-0.5 text-sm leading-relaxed text-ink-soft">{l.line}</p>
              </div>
            </li>
          ))}
        </ul>
      </div>

      <div className="flex flex-col justify-center gap-8">
        {MODELS.map((m) => (
          <figure key={m.name}>
            <figcaption className="mb-2.5 flex items-baseline justify-between gap-3 text-sm">
              <span className="font-semibold text-ink">{m.name}</span>
              <span className="text-muted">{m.note}</span>
            </figcaption>
            <div
              className="flex h-12 overflow-hidden rounded-xl ring-1 ring-line"
              role="img"
              aria-label={`${m.name} default weights: principles ${m.weights[0]}%, evidence ${m.weights[1]}%, signals ${m.weights[2]}%`}
            >
              {LAYERS.map((l, i) => (
                <div
                  key={l.key}
                  className={`${l.bar} flex min-w-1 items-center justify-center text-xs font-semibold`}
                  style={{ width: `${m.weights[i]}%` }}
                >
                  {m.weights[i] >= 8 && (
                    <span>
                      {l.key} · {m.weights[i]}%
                    </span>
                  )}
                </div>
              ))}
            </div>
            {m.weights[2] < 8 && <p className="mt-1.5 text-right text-xs text-muted">L3 · {m.weights[2]}%</p>}
          </figure>
        ))}
        <p className="text-xs text-muted">Default weight shares. Managers can tune them per model.</p>
      </div>
    </div>
  );
}
import { Ear, History, ListChecks, Scale, type LucideIcon } from "lucide-react";
import { LayerWeights } from "./LayerWeights";

const STEPS: { n: number; title: string; body: string; Icon: LucideIcon }[] = [
  { n: 1, title: "Listen", body: "Collect what customers say, market by market.", Icon: Ear },
  { n: 2, title: "Weigh", body: "Score every signal across three layers, with weights tuned for each model.", Icon: Scale },
  {
    n: 3,
    title: "Decide",
    body: "The AI drafts most requirements as SMART targets. The product manager keeps, edits, postpones or rejects each one, with a reason.",
    Icon: ListChecks,
  },
  {
    n: 4,
    title: "Remember",
    body: "Every decision, its reason and its evidence are stored. The AI reads that memory; the PM can edit it.",
    Icon: History,
  },
];

export function Process() {
  return (
    <section id="process" aria-labelledby="process-title" className="scroll-mt-20 border-y border-line bg-bg-soft">
      <div className="mx-auto max-w-6xl px-4 py-20 sm:px-6 lg:py-28">
        <div className="max-w-2xl">
          <p className="text-sm font-semibold text-brand">How it works</p>
          <h2 id="process-title" className="mt-2 text-3xl font-semibold tracking-tight text-ink text-balance sm:text-4xl">
            From a customer comment to a requirement, in four steps.
          </h2>
        </div>

        <ol className="mt-12 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {STEPS.map(({ n, title, body, Icon }) => (
            <li
              key={n}
              className="group relative rounded-card bg-surface p-6 shadow-card ring-1 ring-line transition-shadow duration-200 hover:shadow-float motion-reduce:transition-none"
            >
              <div className="flex items-center justify-between">
                <span className="grid size-10 place-items-center rounded-xl bg-brand-soft text-brand-deep">
                  <Icon className="size-5" aria-hidden />
                </span>
                <span className="font-mono text-xs text-muted">0{n}</span>
              </div>
              <h3 className="mt-5 text-lg font-semibold text-ink">{title}</h3>
              <p className="mt-2 text-sm leading-relaxed text-ink-soft">{body}</p>
            </li>
          ))}
        </ol>

        <LayerWeights />
      </div>
    </section>
  );
}
import { existsSync } from "node:fs";
import path from "node:path";
import Image from "next/image";
import type { ReactNode } from "react";
import { CircleHelp, GitBranch, UserCheck, type LucideIcon } from "lucide-react";
import { ProductMock } from "./ProductMock";

const PHOTO_SRC = "/images/product-dashboard.png";

const FEATURES: { title: string; body: string; Icon: LucideIcon }[] = [
  { title: "Lineage", body: "Follow any requirement back to the comments, studies and sales data behind it.", Icon: GitBranch },
  { title: "Human in the loop", body: "The AI drafts. The product manager decides, and every decision carries a reason.", Icon: UserCheck },
  { title: "What we don't know", body: "Missing markets, thin samples and conflicting signals are shown, not hidden.", Icon: CircleHelp },
];

function Quote({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <blockquote className={`text-2xl leading-tight font-semibold tracking-tight text-ink text-balance sm:text-3xl ${className ?? ""}`}>
      <p>{children}</p>
    </blockquote>
  );
}

export function Product() {
  // The photo is generated separately; only render it once the file is actually there.
  const hasPhoto = existsSync(path.join(process.cwd(), "public", PHOTO_SRC));

  return (
    <section id="product" aria-labelledby="product-title" className="scroll-mt-20">
      <div className="mx-auto max-w-6xl px-4 py-20 sm:px-6 lg:py-28">
        <p className="text-sm font-semibold text-brand">Product</p>
        <h2 id="product-title" className="mt-2 max-w-3xl text-4xl font-semibold tracking-tight text-ink text-balance sm:text-5xl">
          Every requirement, <span className="text-brand">traceable to its source.</span>
        </h2>

        <div className="relative mt-12">
          <div aria-hidden className="absolute -inset-x-6 -inset-y-8 -z-10 rounded-[32px] bg-[radial-gradient(70%_60%_at_50%_30%,var(--brand-soft),transparent_75%)]" />
          <ProductMock />
        </div>

        <div className={`mt-20 grid gap-10 ${hasPhoto ? "lg:grid-cols-2 lg:items-center" : ""}`}>
          <div className={`grid gap-10 ${hasPhoto ? "" : "md:grid-cols-2 md:gap-16"}`}>
            <div className="border-l-2 border-brand pl-6">
              <Quote>
                The PM decides. <span className="text-muted">The AI shows its work.</span>
              </Quote>
            </div>
            <div className="border-l-2 border-wait pl-6">
              <Quote>
                Know what you don&apos;t know. <span className="text-muted">Gaps are flagged, never averaged away.</span>
              </Quote>
            </div>
          </div>
          {hasPhoto && (
            <figure>
              <div className="overflow-hidden rounded-card bg-bg-soft shadow-float ring-1 ring-line">
              <Image
                src={PHOTO_SRC}
                alt="AI concept image: the Dixi dashboard on a laptop, with a globe, a ranked requirement list and blue charts"
                width={1536}
                height={1024}
                sizes="(min-width: 1024px) 560px, 100vw"
                className="h-auto w-full"
              />
              </div>
              <figcaption className="mt-2.5 text-xs text-muted">
                <span className="mr-1.5 rounded bg-surface px-1.5 py-0.5 font-medium text-ink-soft ring-1 ring-line">AI-generated image</span>
                Concept render of the dashboard.
              </figcaption>
            </figure>
          )}
        </div>

        <ul className="mt-20 grid gap-8 border-t border-line pt-10 md:grid-cols-3">
          {FEATURES.map(({ title, body, Icon }) => (
            <li key={title}>
              <Icon className="size-5 text-brand" aria-hidden />
              <h3 className="mt-3 font-semibold text-ink">{title}</h3>
              <p className="mt-1.5 text-sm leading-relaxed text-ink-soft">{body}</p>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
/* Coded product preview: a small, static dashboard mock built from divs (sample content, not BMW data). */
import { TriangleAlert, Check, Clock, GitBranch, Pencil, X } from "lucide-react";

type Status = "kept" | "edited" | "postponed" | "rejected";

const STATUS: Record<Status, { label: string; cls: string; Icon: typeof Check }> = {
  kept: { label: "Kept", cls: "bg-good-soft text-good", Icon: Check },
  edited: { label: "Edited", cls: "bg-brand-soft text-brand-deep", Icon: Pencil },
  postponed: { label: "Postponed", cls: "bg-wait-soft text-wait", Icon: Clock },
  rejected: { label: "Rejected", cls: "bg-bad-soft text-bad", Icon: X },
};

const ROWS: { id: string; title: string; score: number; mix: [number, number, number]; status: Status }[] = [
  { id: "R-12", title: "Climate controls reachable without the touchscreen", score: 86, mix: [20, 72, 8], status: "kept" },
  { id: "R-07", title: "Phone pairs in under 5 s on 95% of attempts", score: 78, mix: [10, 80, 10], status: "edited" },
  { id: "R-21", title: "Body width fits standard Japanese car parks", score: 74, mix: [70, 28, 2], status: "kept" },
  { id: "R-30", title: "Monthly over-the-air feature updates", score: 61, mix: [5, 50, 45], status: "postponed" },
  { id: "R-33", title: "Paid subscription for heated seats", score: 22, mix: [0, 60, 40], status: "rejected" },
];

function Mix({ mix }: { mix: [number, number, number] }) {
  return (
    <div className="flex h-1.5 w-16 overflow-hidden rounded-full bg-bg-soft" aria-hidden>
      <span className="bg-l1" style={{ width: `${mix[0]}%` }} />
      <span className="bg-l2" style={{ width: `${mix[1]}%` }} />
      <span className="bg-l3" style={{ width: `${mix[2]}%` }} />
    </div>
  );
}

export function ProductMock() {
  return (
    <div
      role="img"
      aria-label="Preview of the Dixi dashboard: a list of draft requirements with scores, layer mix and the product manager's decision, a lineage trail and an evidence-gap warning."
      className="overflow-hidden rounded-[18px] bg-surface shadow-float ring-1 ring-line"
    >
      {/* window chrome */}
      <div className="flex items-center gap-2 border-b border-line bg-bg-soft px-4 py-2.5">
        <span className="size-2.5 rounded-full bg-line" />
        <span className="size-2.5 rounded-full bg-line" />
        <span className="size-2.5 rounded-full bg-line" />
        <span className="ml-3 truncate rounded-md bg-surface px-3 py-0.5 font-mono text-[11px] text-muted ring-1 ring-line">
          dixi / 7 Series successor / requirements
        </span>
      </div>

      <div className="grid md:grid-cols-[1fr_250px]">
        {/* requirements table */}
        <div className="min-w-0 p-4 sm:p-5">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <p className="text-sm font-semibold text-ink">Draft requirements</p>
            <div className="flex gap-1.5 text-[11px] font-medium">
              {["All markets", "EU", "CN", "US", "JP"].map((t, i) => (
                <span key={t} className={`rounded-full px-2 py-0.5 ${i === 0 ? "bg-brand text-white" : "bg-bg-soft text-ink-soft"}`}>
                  {t}
                </span>
              ))}
            </div>
          </div>
          <ul className="mt-4 divide-y divide-line">
            {ROWS.map((r, i) => {
              const s = STATUS[r.status];
              return (
                <li key={r.id} className={`flex items-center gap-3 py-2.5 ${i === 1 ? "-mx-2 rounded-lg bg-brand-soft/60 px-2" : ""}`}>
                  <span className="hidden w-10 shrink-0 font-mono text-[11px] text-muted sm:block">{r.id}</span>
                  <span className="min-w-0 flex-1 truncate text-[13px] text-ink">{r.title}</span>
                  <span className="hidden sm:block">
                    <Mix mix={r.mix} />
                  </span>
                  <span className="w-7 shrink-0 text-right font-mono text-xs font-semibold text-ink-soft">{r.score}</span>
                  <span className={`inline-flex w-[88px] shrink-0 items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-medium ${s.cls}`}>
                    <s.Icon className="size-3" aria-hidden />
                    {s.label}
                  </span>
                </li>
              );
            })}
          </ul>
        </div>

        {/* side panel: lineage + gaps */}
        <aside className="border-t border-line bg-bg-soft/60 p-4 sm:p-5 md:border-t-0 md:border-l">
          <p className="flex items-center gap-1.5 text-xs font-semibold text-ink">
            <GitBranch className="size-3.5 text-brand" aria-hidden /> Lineage · R-07
          </p>
          <ol className="mt-3 space-y-2.5 border-l-2 border-line pl-3 text-[12px]">
            <li>
              <span className="text-muted">Comment</span>
              <p className="text-ink-soft">“CarPlay drops out too often.”</p>
            </li>
            <li>
              <span className="text-muted">Evidence</span>
              <p className="text-ink-soft">Owner feedback, US · 3 sources</p>
            </li>
            <li>
              <span className="text-muted">AI draft</span>
              <p className="text-ink-soft">Pairs in under 8 s</p>
            </li>
            <li>
              <span className="font-medium text-human">PM decision</span>
              <p className="text-ink-soft">Tightened to 5 s: matches rivals</p>
            </li>
          </ol>
          <div className="mt-4 rounded-lg bg-wait-soft p-2.5 text-[12px] text-ink-soft ring-1 ring-wait/20">
            <p className="flex items-center gap-1.5 font-semibold text-wait">
              <TriangleAlert className="size-3.5" aria-hidden /> What we don&apos;t know
            </p>
            <p className="mt-1">Japan: thin sample (n = 14). EU and CN signals conflict.</p>
          </div>
        </aside>
      </div>
    </div>
  );
}
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { Logo } from "@/components/brand/Logo";
import { ButtonLink } from "./ButtonLink";

const LINKS = [
  { href: "#process", label: "Process" },
  { href: "#product", label: "Product" },
  { href: "#contact", label: "Contact" },
];

export function Navbar() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 8);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header
      className={`sticky top-0 z-50 border-b transition-[background-color,border-color,box-shadow] duration-200 motion-reduce:transition-none ${
        scrolled ? "border-line bg-bg/80 shadow-card backdrop-blur-md" : "border-transparent bg-bg/0"
      }`}
    >
      <nav aria-label="Main" className="mx-auto flex h-16 max-w-6xl items-center justify-between gap-4 px-4 sm:px-6">
        <Link href="/" aria-label="Dixi home" className="shrink-0">
          <Logo size={28} />
        </Link>
        <ul className="hidden items-center gap-1 md:flex">
          {LINKS.map((l) => (
            <li key={l.href}>
              <a href={l.href} className="rounded-full px-3 py-2 text-sm font-medium text-ink-soft transition-colors hover:text-ink">
                {l.label}
              </a>
            </li>
          ))}
        </ul>
        <ButtonLink href="/dashboard" size="sm">
          Open dashboard
        </ButtonLink>
      </nav>
    </header>
  );
}
import Link from "next/link";
import type { ComponentProps } from "react";

type Variant = "primary" | "secondary" | "ghost";

const base =
  "inline-flex items-center justify-center gap-2 rounded-full font-medium whitespace-nowrap transition-colors duration-150 motion-reduce:transition-none";

const variants: Record<Variant, string> = {
  primary: "bg-brand text-white shadow-card hover:bg-brand-deep",
  secondary: "bg-surface text-ink ring-1 ring-line hover:bg-bg-soft hover:ring-brand/30",
  ghost: "text-ink-soft hover:text-ink",
};

const sizes = { sm: "h-9 px-4 text-sm", md: "h-11 px-5 text-[0.95rem]" };

type Props = ComponentProps<typeof Link> & { variant?: Variant; size?: keyof typeof sizes };

/** Pill button that navigates (next/link). Use for in-app routes and in-page anchors. */
export function ButtonLink({ variant = "primary", size = "md", className, ...rest }: Props) {
  return <Link {...rest} className={`${base} ${variants[variant]} ${sizes[size]} ${className ?? ""}`} />;
}

